package br.com.athletix.tarefa.service;
import br.com.athletix.atletica.repository.AtleticaRepository; import br.com.athletix.auditoria.service.AtividadeUsuarioService; import br.com.athletix.departamento.repository.DepartamentoRepository; import br.com.athletix.evento.service.EventoService; import br.com.athletix.gestao.entity.StatusGestao; import br.com.athletix.gestao.repository.GestaoRepository; import br.com.athletix.membro.entity.*; import br.com.athletix.membro.repository.MembroRepository; import br.com.athletix.shared.exception.*; import br.com.athletix.shared.normalization.NomeNormalizado; import br.com.athletix.shared.tenancy.AtleticaResourceResolver; import br.com.athletix.tarefa.dto.TarefaRequests; import br.com.athletix.tarefa.entity.*; import br.com.athletix.tarefa.repository.TarefaRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class TarefaService { final TarefaRepository r; final EventoService e; final AtleticaRepository a; final MembroRepository m; final DepartamentoRepository d; final GestaoRepository g; final AtleticaResourceResolver x; final AtividadeUsuarioService audit; public TarefaService(TarefaRepository r,EventoService e,AtleticaRepository a,MembroRepository m,DepartamentoRepository d,GestaoRepository g,AtleticaResourceResolver x,AtividadeUsuarioService audit){this.r=r;this.e=e;this.a=a;this.m=m;this.d=d;this.g=g;this.x=x;this.audit=audit;} @Transactional public Tarefa criar(TarefaRequests.Create q,Membro autor){var ev=e.buscarDaAtleticaAtual(q.eventoId());var at=x.requireByIdAndAtleticaId(x.atleticaIdAtual(),a::findByIdAndId);var t=r.save(new Tarefa(at,g.findByAtletica_IdAndStatus(x.atleticaIdAtual(),StatusGestao.ATIVA).map(z->z.getId()).orElse(null),ev,NomeNormalizado.displayValue(q.titulo()),NomeNormalizado.optionalDisplayValue(q.descricao()),q.responsavelMembroId()==null?null:x.requireByIdAndAtleticaId(q.responsavelMembroId(),m::findByIdAndAtletica_Id),q.departamentoId()==null?null:x.requireByIdAndAtleticaId(q.departamentoId(),d::findByIdAndAtletica_Id),q.prioridade(),q.prazo(),autor.getId()));audit.registrar("TAREFA_CRIADA","TAREFA",t.getId(),"Tarefa criada.");return t;} @Transactional(readOnly=true) public Tarefa buscar(Long id){return x.requireByIdAndAtleticaId(id,r::findByIdAndAtletica_Id);} @Transactional public Tarefa alterar(Long id,TarefaRequests.Update q){var t=buscar(id);if(!t.getVersion().equals(q.version()))throw new br.com.athletix.shared.exception.ConcurrentModificationException();t.atualizar(NomeNormalizado.displayValue(q.titulo()),NomeNormalizado.optionalDisplayValue(q.descricao()),q.responsavelMembroId()==null?null:x.requireByIdAndAtleticaId(q.responsavelMembroId(),m::findByIdAndAtletica_Id),q.departamentoId()==null?null:x.requireByIdAndAtleticaId(q.departamentoId(),d::findByIdAndAtletica_Id),q.prioridade(),q.prazo());audit.registrar("TAREFA_ATUALIZADA","TAREFA",id,"Tarefa atualizada.");return t;} @Transactional public Tarefa status(Long id,TarefaRequests.Status q){var t=buscar(id);if(!t.getVersion().equals(q.version()))throw new br.com.athletix.shared.exception.ConcurrentModificationException(); if(q.status()==StatusTarefa.EM_ANDAMENTO&&(t.getStatus()==StatusTarefa.REVISAO||t.getStatus()==StatusTarefa.CONCLUIDO)&&NomeNormalizado.optionalDisplayValue(q.motivo())==null)throw new BusinessRuleException("Informe o motivo do retorno.");t.status(q.status());audit.registrar(q.status()==StatusTarefa.CONCLUIDO?"TAREFA_CONCLUIDA":"TAREFA_STATUS_ATUALIZADO","TAREFA",id,"Status atualizado.");return t;}}
